package telemetry

// 3D telemetry (spec D-190): placing the game's track on the real world.
//
// Every track SetupMan knows has the OpenStreetMap race track lines around it (geotracks.go,
// generated by Telemetry/trackmaps/gen_geo.py). Positions are kept in metres east (E) and north
// (N) of the track's origin; the browser turns them back into latitude and longitude for the photo
// tiles. The game's own coordinates (or a line calculated from speed and yaw rate) are fitted onto
// those lines once per track: turned, shifted, and mirrored when the game's axes are.

import (
	"math"
	"sort"
)

const earthR = 6378137.0 // metres (the radius web map tiles use)

// GeoTrack is the real-world data shipped for one track.
type GeoTrack struct {
	Lat, Lon float64     // origin
	Ways     [][]float32 // OpenStreetMap race track lines: E, N pairs in metres from the origin
}

// Geo returns the shipped data of a track (ok false when SetupMan has none).
func Geo(track string) (GeoTrack, bool) {
	g, ok := geoTracks[track]
	return g, ok
}

// GeoFit turns game coordinates (x, z) into E, N: first z is mirrored when Mirror, then the
// point is scaled, turned by Angle (radians, anticlockwise) and shifted.
type GeoFit struct {
	Mirror bool    `json:"mirror"`
	Angle  float64 `json:"angle"`
	Scale  float64 `json:"scale"`
	E      float64 `json:"e"`
	N      float64 `json:"n"`
	RMS    float64 `json:"rms"`    // metres: how far the fitted line lies from the OSM lines (closest 80 %)
	Points int     `json:"points"` // points used
}

// Apply turns one game point into E, N.
func (f GeoFit) Apply(x, z float64) (e, n float64) {
	if f.Mirror {
		z = -z
	}
	c, s := math.Cos(f.Angle)*f.Scale, math.Sin(f.Angle)*f.Scale
	return c*x - s*z + f.E, s*x + c*z + f.N
}

// segIndex finds the OSM line closest to a point, with a grid of cells.
type segIndex struct {
	seg  [][4]float64 // e1 n1 e2 n2
	cell float64
	grid map[[2]int32][]int32
}

func newSegIndex(ways [][]float32) *segIndex {
	ix := &segIndex{cell: 25, grid: map[[2]int32][]int32{}}
	for _, w := range ways {
		for i := 0; i+3 < len(w); i += 2 {
			s := [4]float64{float64(w[i]), float64(w[i+1]), float64(w[i+2]), float64(w[i+3])}
			k := int32(len(ix.seg))
			ix.seg = append(ix.seg, s)
			c0, c1 := ix.key(min(s[0], s[2]), min(s[1], s[3])), ix.key(max(s[0], s[2]), max(s[1], s[3]))
			for a := c0[0]; a <= c1[0]; a++ {
				for b := c0[1]; b <= c1[1]; b++ {
					ix.grid[[2]int32{a, b}] = append(ix.grid[[2]int32{a, b}], k)
				}
			}
		}
	}
	return ix
}

func (ix *segIndex) key(e, n float64) [2]int32 {
	return [2]int32{int32(math.Floor(e / ix.cell)), int32(math.Floor(n / ix.cell))}
}

// nearest returns the closest point on any line within about 2 cells, and its distance
// (limit when nothing is that close).
func (ix *segIndex) nearest(e, n, limit float64) (pe, pn, d float64) {
	k := ix.key(e, n)
	best := limit * limit
	pe, pn = e, n
	r := int32(math.Ceil(limit / ix.cell))
	for a := k[0] - r; a <= k[0]+r; a++ {
		for b := k[1] - r; b <= k[1]+r; b++ {
			for _, i := range ix.grid[[2]int32{a, b}] {
				s := ix.seg[i]
				dx, dy := s[2]-s[0], s[3]-s[1]
				t := 0.0
				if l := dx*dx + dy*dy; l > 0 {
					t = math.Max(0, math.Min(1, ((e-s[0])*dx+(n-s[1])*dy)/l))
				}
				qe, qn := s[0]+t*dx, s[1]+t*dy
				if dd := (qe-e)*(qe-e) + (qn-n)*(qn-n); dd < best {
					best, pe, pn = dd, qe, qn
				}
			}
		}
	}
	return pe, pn, math.Sqrt(best)
}

// FitToGeo fits a lap's line (game x, z in metres) onto the track's OSM lines. freeScale lets the
// size change too (for a line calculated from speed and yaw rate; the game's own positions are
// in metres already). ok is false when no good fit was found (RMS over 6 m).
func FitToGeo(g GeoTrack, xs, zs []float64, freeScale bool) (GeoFit, bool) {
	if len(xs) < 50 || len(g.Ways) == 0 {
		return GeoFit{}, false
	}
	ix := newSegIndex(g.Ways)
	// the line about every 5 m, centred
	var px, pz []float64
	cx, cz := 0.0, 0.0
	for i := range xs {
		if i > 0 && len(px) > 0 && math.Hypot(xs[i]-px[len(px)-1], zs[i]-pz[len(pz)-1]) < 5 {
			continue
		}
		px, pz = append(px, xs[i]), append(pz, zs[i])
	}
	for i := range px {
		cx, cz = cx+px[i], cz+pz[i]
	}
	cx, cz = cx/float64(len(px)), cz/float64(len(pz))
	for i := range px {
		px[i], pz[i] = px[i]-cx, pz[i]-cz
	}
	// coarse search over turn, mirror and shift, scored on a grid of distances to the OSM lines
	dg := newDistGrid(ix, 10)
	span := math.Max(dg.cols, dg.rows) * dg.cell
	step := math.Max(20, span/90)
	type cand struct {
		f     GeoFit
		score float64
	}
	var cands []cand
	sub := max(1, len(px)/80) // about 80 points
	score := func(f GeoFit) float64 {
		var s float64
		for i := 0; i < len(px); i += sub {
			e, n := f.Apply(px[i], pz[i])
			s += math.Min(dg.at(e, n), 3*step)
		}
		return s
	}
	for _, mirror := range []bool{false, true} {
		for a := 0; a < 360; a += 3 {
			best := cand{score: math.Inf(1)}
			for de := dg.e0; de <= dg.e0+dg.cols*dg.cell; de += step {
				for dn := dg.n0; dn <= dg.n0+dg.rows*dg.cell; dn += step {
					f := GeoFit{Mirror: mirror, Angle: float64(a) * math.Pi / 180, Scale: 1, E: de, N: dn}
					if s := score(f); s < best.score {
						best = cand{f, s}
					}
				}
			}
			// finer shift around the best one
			for k := 0; k < 3; k++ {
				st := step / float64(int(2)<<k)
				c := best.f
				for de := -2.0; de <= 2; de++ {
					for dn := -2.0; dn <= 2; dn++ {
						f := c
						f.E, f.N = c.E+de*st, c.N+dn*st
						if s := score(f); s < best.score {
							best = cand{f, s}
						}
					}
				}
			}
			cands = append(cands, best)
		}
	}
	sort.Slice(cands, func(i, j int) bool { return cands[i].score < cands[j].score })
	var out GeoFit
	bestRMS := math.Inf(1)
	for _, c := range cands[:min(6, len(cands))] {
		f := refine(ix, px, pz, c.f, freeScale)
		if f.RMS < bestRMS {
			bestRMS, out = f.RMS, f
		}
	}
	// back to the uncentred game coordinates: e = R·(p − c) + t  →  t' = t − R·c
	ce, cn := out.Apply(cx, cz)
	oe, on := out.Apply(0, 0)
	out.E -= ce - oe
	out.N -= cn - on
	out.Points = len(px)
	return out, out.RMS <= 6
}

// refine improves a fit by pairing every point with its closest OSM point and solving for the best
// turn and shift (2D Procrustes), leaving out the 20 % worst pairs (pit lane, other layouts).
func refine(ix *segIndex, px, pz []float64, f GeoFit, freeScale bool) GeoFit {
	limit := 40.0
	for it := 0; it < 40; it++ {
		type pair struct{ x, z, e, n, d float64 }
		var ps []pair
		for i := range px {
			x, z := px[i], pz[i]
			if f.Mirror {
				z = -z
			}
			e, n := f.Apply(px[i], pz[i])
			qe, qn, d := ix.nearest(e, n, limit)
			if d < limit {
				ps = append(ps, pair{x, z, qe, qn, d})
			}
		}
		if len(ps) < 30 {
			f.RMS = math.Inf(1)
			return f
		}
		sort.Slice(ps, func(i, j int) bool { return ps[i].d < ps[j].d })
		ps = ps[:len(ps)*8/10]
		var mx, mz, me, mn float64
		for _, p := range ps {
			mx, mz, me, mn = mx+p.x, mz+p.z, me+p.e, mn+p.n
		}
		k := float64(len(ps))
		mx, mz, me, mn = mx/k, mz/k, me/k, mn/k
		var sxx, sxy, ss float64 // cross terms for the best angle
		for _, p := range ps {
			ax, az, be, bn := p.x-mx, p.z-mz, p.e-me, p.n-mn
			sxx += ax*be + az*bn
			sxy += ax*bn - az*be
			ss += ax*ax + az*az
		}
		f.Angle = math.Atan2(sxy, sxx)
		f.Scale = 1
		if freeScale && ss > 0 {
			f.Scale = math.Hypot(sxx, sxy) / ss
		}
		c, s := math.Cos(f.Angle)*f.Scale, math.Sin(f.Angle)*f.Scale
		f.E, f.N = me-(c*mx-s*mz), mn-(s*mx+c*mz)
		rms := 0.0
		for _, p := range ps {
			rms += p.d * p.d
		}
		f.RMS = math.Sqrt(rms / k)
		limit = math.Max(10, math.Min(limit, f.RMS*4))
	}
	return f
}

// distGrid holds, per cell, the distance to the closest OSM line (chamfer distance transform).
type distGrid struct {
	e0, n0, cell float64
	cols, rows   float64
	d            []float32
}

func newDistGrid(ix *segIndex, cell float64) *distGrid {
	e0, n0, e1, n1 := math.Inf(1), math.Inf(1), math.Inf(-1), math.Inf(-1)
	for _, s := range ix.seg {
		e0, e1 = math.Min(e0, math.Min(s[0], s[2])), math.Max(e1, math.Max(s[0], s[2]))
		n0, n1 = math.Min(n0, math.Min(s[1], s[3])), math.Max(n1, math.Max(s[1], s[3]))
	}
	m := 300.0
	g := &distGrid{e0: e0 - m, n0: n0 - m, cell: cell}
	g.cols, g.rows = math.Ceil((e1-e0+2*m)/cell), math.Ceil((n1-n0+2*m)/cell)
	c, r := int(g.cols), int(g.rows)
	g.d = make([]float32, c*r)
	for i := range g.d {
		g.d[i] = 1e9
	}
	for _, s := range ix.seg { // mark the cells the lines cross
		l := math.Hypot(s[2]-s[0], s[3]-s[1])
		for t := 0.0; t <= l; t += cell / 2 {
			k := t / math.Max(l, 1e-9)
			x, y := int((s[0]+k*(s[2]-s[0])-g.e0)/cell), int((s[1]+k*(s[3]-s[1])-g.n0)/cell)
			if x >= 0 && y >= 0 && x < c && y < r {
				g.d[y*c+x] = 0
			}
		}
	}
	a, b := float32(cell), float32(cell*math.Sqrt2)
	for y := 0; y < r; y++ { // forward pass
		for x := 0; x < c; x++ {
			v := g.d[y*c+x]
			if x > 0 {
				v = min(v, g.d[y*c+x-1]+a)
			}
			if y > 0 {
				v = min(v, g.d[(y-1)*c+x]+a)
				if x > 0 {
					v = min(v, g.d[(y-1)*c+x-1]+b)
				}
				if x < c-1 {
					v = min(v, g.d[(y-1)*c+x+1]+b)
				}
			}
			g.d[y*c+x] = v
		}
	}
	for y := r - 1; y >= 0; y-- { // backward pass
		for x := c - 1; x >= 0; x-- {
			v := g.d[y*c+x]
			if x < c-1 {
				v = min(v, g.d[y*c+x+1]+a)
			}
			if y < r-1 {
				v = min(v, g.d[(y+1)*c+x]+a)
				if x < c-1 {
					v = min(v, g.d[(y+1)*c+x+1]+b)
				}
				if x > 0 {
					v = min(v, g.d[(y+1)*c+x-1]+b)
				}
			}
			g.d[y*c+x] = v
		}
	}
	return g
}

// at is the distance at a point (large outside the grid).
func (g *distGrid) at(e, n float64) float64 {
	x, y := int((e-g.e0)/g.cell), int((n-g.n0)/g.cell)
	if x < 0 || y < 0 || x >= int(g.cols) || y >= int(g.rows) {
		return 1e6
	}
	return float64(g.d[y*int(g.cols)+x])
}

// LatLon turns E, N back into latitude and longitude (good to centimetres over a few km).
func (g GeoTrack) LatLon(e, n float64) (lat, lon float64) {
	lat = g.Lat + n/earthR*180/math.Pi
	lon = g.Lon + e/(earthR*math.Cos(g.Lat*math.Pi/180))*180/math.Pi
	return
}

// EN turns latitude and longitude into E, N.
func (g GeoTrack) EN(lat, lon float64) (e, n float64) {
	n = (lat - g.Lat) * math.Pi / 180 * earthR
	e = (lon - g.Lon) * math.Pi / 180 * earthR * math.Cos(g.Lat*math.Pi/180)
	return
}

// Near tells whether a point lies within limit metres of one of the OSM lines.
func (g GeoTrack) Near(e, n, limit float64) bool {
	for _, w := range g.Ways {
		for i := 0; i+3 < len(w); i += 2 {
			x1, y1, x2, y2 := float64(w[i]), float64(w[i+1]), float64(w[i+2]), float64(w[i+3])
			dx, dy := x2-x1, y2-y1
			t := 0.0
			if l := dx*dx + dy*dy; l > 0 {
				t = math.Max(0, math.Min(1, ((e-x1)*dx+(n-y1)*dy)/l))
			}
			if math.Hypot(x1+t*dx-e, y1+t*dy-n) <= limit {
				return true
			}
		}
	}
	return false
}

// Bounds is the area of the OSM lines plus margin metres around them.
func (g GeoTrack) Bounds(margin float64) (e0, n0, e1, n1 float64) {
	e0, n0, e1, n1 = math.Inf(1), math.Inf(1), math.Inf(-1), math.Inf(-1)
	for _, w := range g.Ways {
		for i := 0; i+1 < len(w); i += 2 {
			e0, e1 = math.Min(e0, float64(w[i])), math.Max(e1, float64(w[i]))
			n0, n1 = math.Min(n0, float64(w[i+1])), math.Max(n1, float64(w[i+1]))
		}
	}
	return e0 - margin, n0 - margin, e1 + margin, n1 + margin
}
